-- 电梯台账导入：设备分类拆分为客梯/货梯/扶梯，导入 78 台电梯设备主数据。
-- 数据来源：《万悦城78台电梯台账_20261113.xlsx》；以 equipment_code（设备代码）为幂等键，可重复执行。
-- 巡检频率与检查项目不在本迁移中固化，由后续的模板与计划配置决定。

-- 1. 现有“电梯”分类改造为“客梯”，并补全台账字段。
UPDATE inspection_equipment_category
   SET name = '客梯',
       system_name = '电梯系统',
       base_fields_json = '[{"key":"dengjiNO","label":"使用登记证编号","controlType":"TEXT"},{"key":"rescueCode","label":"96333应急救援编号","controlType":"TEXT"},{"key":"ratedLoad","label":"额定载重","controlType":"TEXT","unit":"kg"},{"key":"speed","label":"额定速度","controlType":"TEXT","unit":"m/s"},{"key":"floorStations","label":"层站门数","controlType":"TEXT"},{"key":"controlMode","label":"控制方式","controlType":"TEXT"},{"key":"variety","label":"设备品种","controlType":"TEXT"},{"key":"productNo","label":"产品编号","controlType":"TEXT"},{"key":"manufacturer","label":"制造单位","controlType":"TEXT"},{"key":"manufactureDate","label":"制造日期","controlType":"DATE"},{"key":"lastInspectionDate","label":"最近检验日期","controlType":"DATE"},{"key":"inspectionConclusion","label":"检验结论","controlType":"TEXT"},{"key":"reportNo","label":"检验报告编号","controlType":"TEXT"},{"key":"nextInspectionMonth","label":"下次检验(年月)","controlType":"TEXT"},{"key":"reportSource","label":"报告资料来源","controlType":"TEXT"},{"key":"certSource","label":"使用标志资料来源","controlType":"TEXT"}]'
 WHERE code = 'ELEVATOR';

-- 2. 新增货梯、扶梯分类。
VALUES('ELEVATOR_FREIGHT','货梯','电梯系统','[{"key":"dengjiNO","label":"使用登记证编号","controlType":"TEXT"},{"key":"ratedLoad","label":"额定载重","controlType":"TEXT","unit":"kg"},{"key":"speed","label":"额定速度","controlType":"TEXT","unit":"m/s"},{"key":"floorStations","label":"层站门数","controlType":"TEXT"},{"key":"controlMode","label":"控制方式","controlType":"TEXT"},{"key":"variety","label":"设备品种","controlType":"TEXT"},{"key":"productNo","label":"产品编号","controlType":"TEXT"},{"key":"manufacturer","label":"制造单位","controlType":"TEXT"},{"key":"manufactureDate","label":"制造日期","controlType":"DATE"},{"key":"lastInspectionDate","label":"最近检验日期","controlType":"DATE"},{"key":"inspectionConclusion","label":"检验结论","controlType":"TEXT"},{"key":"reportNo","label":"检验报告编号","controlType":"TEXT"},{"key":"nextInspectionMonth","label":"下次检验(年月)","controlType":"TEXT"},{"key":"reportSource","label":"报告资料来源","controlType":"TEXT"},{"key":"certSource","label":"使用标志资料来源","controlType":"TEXT"}]','载货电梯',61,1)
ON DUPLICATE KEY UPDATE name=VALUES(name),system_name=VALUES(system_name),base_fields_json=VALUES(base_fields_json),description=VALUES(description),sort_order=VALUES(sort_order);

VALUES('ELEVATOR_ESCALATOR','扶梯','电梯系统','[{"key":"dengjiNO","label":"使用登记证编号","controlType":"TEXT"},{"key":"nominalSpeed","label":"名义速度","controlType":"TEXT","unit":"m/s"},{"key":"nominalWidth","label":"名义宽度","controlType":"TEXT","unit":"mm"},{"key":"inclination","label":"倾斜角","controlType":"TEXT","unit":"°"},{"key":"capacity","label":"输送能力","controlType":"TEXT","unit":"P/h"},{"key":"liftingHeight","label":"提升高度","controlType":"TEXT","unit":"m"},{"key":"variety","label":"设备品种","controlType":"TEXT"},{"key":"productNo","label":"产品编号","controlType":"TEXT"},{"key":"manufacturer","label":"制造单位","controlType":"TEXT"},{"key":"manufactureDate","label":"制造日期","controlType":"DATE"},{"key":"lastInspectionDate","label":"最近检验日期","controlType":"DATE"},{"key":"inspectionConclusion","label":"检验结论","controlType":"TEXT"},{"key":"reportNo","label":"检验报告编号","controlType":"TEXT"},{"key":"nextInspectionMonth","label":"下次检验(年月)","controlType":"TEXT"},{"key":"reportSource","label":"报告资料来源","controlType":"TEXT"},{"key":"certSource","label":"使用标志资料来源","controlType":"TEXT"}]','自动扶梯',62,1)
ON DUPLICATE KEY UPDATE name=VALUES(name),system_name=VALUES(system_name),base_fields_json=VALUES(base_fields_json),description=VALUES(description),sort_order=VALUES(sort_order);

SET @cat_passenger = (SELECT id FROM inspection_equipment_category WHERE code='ELEVATOR');
SET @cat_freight = (SELECT id FROM inspection_equipment_category WHERE code='ELEVATOR_FREIGHT');
SET @cat_escalator = (SELECT id FROM inspection_equipment_category WHERE code='ELEVATOR_ESCALATOR');

-- 3. 清理手工空分类“客梯”（KT），停用测试设备与测试计划。
DELETE FROM inspection_equipment_category
 WHERE code = 'KT'
   AND NOT EXISTS (SELECT 1 FROM inspection_equipment e WHERE e.category_id = inspection_equipment_category.id)
   AND NOT EXISTS (SELECT 1 FROM inspection_category_template t WHERE t.category_id = inspection_equipment_category.id);

UPDATE inspection_equipment SET enabled = 0 WHERE equipment_code = 'KT01';
UPDATE inspection_plan SET enabled = 0 WHERE id = 7 AND EXISTS (SELECT 1 FROM inspection_plan_target t WHERE t.plan_id = 7 AND t.target_type='INSPECTION_EQUIPMENT' AND t.target_id = '1');

-- 4. 写入 78 台电梯台账。
ON DUPLICATE KEY UPDATE equipment_name=VALUES(equipment_name),category_id=VALUES(category_id),system_name=VALUES(system_name),installation_location=VALUES(installation_location),area_name=VALUES(area_name),brand=VALUES(brand),model=VALUES(model),specification=VALUES(specification),serial_number=VALUES(serial_number),maintenance_company=VALUES(maintenance_company),maintenance_phone=VALUES(maintenance_phone),attributes_json=VALUES(attributes_json),remark=VALUES(remark);
